import { test, expect } from '@playwright/test';

test.describe('No Results Found Message - API Response Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display "No results found" message when API returns empty list', async ({ page }) => {
    // Intercept the search API call
    await page.route('**/api/search', (route) => {
      route.abort();
      route.continue();
    });

    // Mock the API response with an empty list
    await page.route('**/api/search', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ results: [] }),
      });
    });

    // Enter search term and click search button
    const searchInput = page.getByPlaceholder('Enter search term');
    await searchInput.fill('nonexistent');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for the results container to appear
    const resultsContainer = page.locator('[data-testid="results-container"]');
    await expect(resultsContainer).toBeVisible();

    // Verify "No results found" message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Verify results list is empty
    const resultsList = page.locator('[data-testid="results-list"]');
    await expect(resultsList).toHaveCount(0);
  });

  test('should handle API error and display appropriate message', async ({ page }) => {
    // Intercept the search API call and mock an error
    await page.route('**/api/search', (route) => {
      route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Internal Server Error' }),
      });
    });

    // Enter search term and click search button
    const searchInput = page.getByPlaceholder('Enter search term');
    await searchInput.fill('test');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).toBeVisible();

    // Verify "No results found" message is NOT displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).not.toBeVisible();

    // Verify results container is visible but empty
    const resultsContainer = page.locator('[data-testid="results-container"]');
    await expect(resultsContainer).toBeVisible();
    const resultsList = page.locator('[data-testid="results-list"]');
    await expect(resultsList).toHaveCount(0);
  });
});
